import pandas as pd

def clean(df):
    d = df.copy()
    for col in ['species', 'island', 'sex']:
        if col in d.columns:
            d[col] = d[col].astype('string').str.strip()
    if 'island' in d.columns:
        d['island'] = d['island'].replace({'biscoe': 'Biscoe'})
    if 'sex' in d.columns:
        d['sex'] = d['sex'].str.lower()
    if 'body_mass_g' in d.columns:
        d['body_mass_g'] = pd.to_numeric(
            d['body_mass_g'].astype('string').str.replace(',', '', regex=False),
            errors='coerce'
        )
    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['sex', 'body_mass_g'])
    d = d[d['sex'].isin(['male', 'female'])]
    return d.groupby('sex')['body_mass_g'].mean().to_dict()
